// Estiu a la masia (EN26), 0.39: the effects. Smoke, swallows, drops, splashes, dust, stars of a bump, falling figs, a sun shower,
// a rainbow, fireflies, lantern light, speed lines, a snore. All pure functions of time, drawn in world coordinates. Names start with mf.
import {MP_TAU,mpRng,mpRgb,mpMix,mpLight,mpDark,mpClamp,mpNoise} from './masia-pinzell.js';
import {msClamp,msEase,msEaseOut,msSpring} from './masia.js';
const MF_TAU=MP_TAU;
// Smoke from the chimney: puffs rising and drifting with the wind, fading; strength 0..1.
export function mfSmoke(c,x,y,t,L,strength=1,wind=-1){if(strength<=0)return;c.save();const n=9;for(let i=0;i<n;i++){const u=((t*.12+i/n)%1);const k=i*1.7;const px=x+wind*u*70+Math.sin(t*.8+k)*5*u,py=y-u*95;const r=6+u*20;c.globalAlpha=.5*strength*(1-u)*Math.min(1,u*6);c.fillStyle=mpRgb(mpMix([236,236,246],L.sun,.2));c.beginPath();c.ellipse(px,py,r,r*.7,0,0,MF_TAU);c.fill();}c.restore();}
// Swallows: n birds on looping paths across the sky; each flaps with its own rhythm. scale 1 at the board.
export function mfSwallows(c,t,n,seed,o={}){const {x0=200,x1=1100,y0=70,y1=260,scale=1,col=[40,36,50]}=o;const r=mpRng(seed);for(let i=0;i<n;i++){const ph=r()*100,sp=.06+r()*.04,amp=30+r()*40;const u=((t*sp+ph)%2);const dir=u<1?1:-1;const uu=u<1?u:2-u;const x=x0+(x1-x0)*uu,y=y0+(y1-y0)*(.5+.5*Math.sin(ph+t*.5))+Math.sin(t*2+ph)*amp*.3;const flap=Math.max(0,Math.sin(t*9+ph));
 c.save();c.translate(x,y);c.scale(dir*scale*(1.3+r()*.5),scale*(1.3+r()*.5));c.fillStyle=mpRgb(col);c.strokeStyle=mpRgb(col);c.lineWidth=1.2;c.lineCap='round';const w=1-flap*1.6;c.beginPath();c.moveTo(-9,-3*w);c.quadraticCurveTo(-4,-1,0,0);c.quadraticCurveTo(4,-1,9,-3*w);c.stroke();c.beginPath();c.moveTo(-1,0);c.lineTo(1,0);c.lineTo(3,3);c.lineTo(0,2);c.lineTo(-3,3);c.closePath();c.fill();c.restore();}}
// Water from a watering can: an arc of drops from (x,y) along direction (dx,dy), strength 0..1.
export function mfWater(c,x,y,dx,dy,t,strength=1,seed=1){if(strength<=0)return;const r=mpRng(seed);c.save();c.fillStyle='rgba(170,215,240,.85)';for(let i=0;i<14;i++){const ph=r();const u=((t*1.4+ph)%1);const px=x+dx*u*50+(r()-.5)*6,py=y+dy*u*20+u*u*60;c.globalAlpha=strength*(1-u*.6);c.beginPath();c.ellipse(px,py,1.6,2.6+u*2,0,0,MF_TAU);c.fill();}c.restore();}
// Rings on the water at (x,y): k rings expanding from time t0, alpha fading.
export function mfRings(c,x,y,t,t0,o={}){const {k=3,speed=28,life=1.8,ry=.38,col=[220,240,250]}=o;if(t<t0)return;c.save();c.lineWidth=1.3;for(let i=0;i<k;i++){const age=t-t0-i*.25;if(age<0||age>life)continue;const R=age*speed;const a=(1-age/life)*.8;c.strokeStyle=mpRgb(col,a);c.beginPath();c.ellipse(x,y,R,R*ry,0,0,MF_TAU);c.stroke();}c.restore();}
// A splash at (x,y) from t0: a crown of drops thrown up and falling back, plus a white burst, 0.9 s.
export function mfSplash(c,x,y,t,t0,size=1,seed=3){const age=t-t0;if(age<0||age>1.1)return;const r=mpRng(seed);c.save();const u=age/1.1;
 c.fillStyle='rgba(255,255,255,'+(.8*(1-u))+')';c.beginPath();c.ellipse(x,y,size*(18+u*30),size*(6+u*8),0,0,MF_TAU);c.fill();
 c.fillStyle='rgba(200,230,250,.9)';for(let i=0;i<16;i++){const a=-Math.PI*(.15+r()*.7),v=(60+r()*70)*size;const px=x+Math.cos(a)*v*age,py=y+Math.sin(a)*v*age+180*age*age;if(py>y+6)continue;c.globalAlpha=1-u;c.beginPath();c.ellipse(px,py,size*2.2,size*(3+r()*2),0,0,MF_TAU);c.fill();}c.restore();}
// Dust puffs at (x,y) from t0 (a landing, a hop), 0.7 s.
export function mfDust(c,x,y,t,t0,size=1,col=[214,196,150]){const age=t-t0;if(age<0||age>.7)return;const u=age/.7;c.save();c.fillStyle=mpRgb(col,.6*(1-u));for(let i=0;i<6;i++){const a=Math.PI+i/5*Math.PI;const d=(10+u*26)*size;c.beginPath();c.ellipse(x+Math.cos(a)*d,y+Math.sin(a)*d*.3-u*6*size,(4+u*8)*size,(3+u*5)*size,0,0,MF_TAU);c.fill();}c.restore();}
// Little stars around a bump at (x,y) from t0, 1 s.
export function mfStars(c,x,y,t,t0,n=5,size=1){const age=t-t0;if(age<0||age>1)return;c.save();for(let i=0;i<n;i++){const a=t*3+i/n*MF_TAU;const R=(14+age*8)*size;const px=x+Math.cos(a)*R,py=y-8*size+Math.sin(a)*R*.5;c.fillStyle=mpRgb([255,220,80],1-age);c.beginPath();for(let k=0;k<5;k++){const aa=k/5*MF_TAU-Math.PI/2+t*2;const rr=k%2?2*size:4.5*size;c.lineTo(px+Math.cos(aa)*rr,py+Math.sin(aa)*rr);}c.closePath();c.fill();}c.restore();}
// A snore: three small bubbles rising from (x,y), looping.
export function mfSnore(c,x,y,t,strength=1,dir=1){if(strength<=0)return;c.save();for(let i=0;i<3;i++){const u=((t*.45+i*.33)%1);const px=x+dir*u*22+Math.sin(u*6)*3,py=y-u*34;const R=(2+u*4);c.globalAlpha=strength*(1-u)*Math.min(1,u*5);c.strokeStyle='rgba(255,255,255,.95)';c.lineWidth=1.4;c.beginPath();c.arc(px,py,R,0,MF_TAU);c.stroke();c.fillStyle='rgba(255,255,255,.5)';c.fill();}c.restore();}
// Figs raining: n figs from the crown (cx,cy,rx,ry) falling to the ground gy, from t0, each with its own delay; they bounce once.
export function mfFigs(c,cx,cy,rx,ry,gy,t,t0,n,seed,L,o={}){const r=mpRng(seed);const {size=1}=o;const fig=[96,60,110];c.save();for(let i=0;i<n;i++){const d=r()*1.4,x=cx+(r()-.5)*rx*1.8,y0=cy+(r()-.5)*ry;const age=t-t0-d;if(age<0)continue;const fall=Math.sqrt(2*(gy+(r()-.5)*20-y0)/420);let y;if(age<fall)y=y0+210*age*age;else{const a2=age-fall;y=a2<.5?gy-Math.sin(a2*Math.PI*2)*18*(1-a2):gy;}
  const ang=age*6*(i%2?1:-1);c.save();c.translate(x,Math.min(y,gy+2));c.rotate(ang);c.fillStyle=mpRgb(fig);c.beginPath();c.ellipse(0,0,4.5*size,5.6*size,0,0,MF_TAU);c.fill();c.fillStyle=mpRgb(mpLight(fig,.5),.6);c.beginPath();c.arc(-1.4*size,-1.6*size,1.4*size,0,MF_TAU);c.fill();c.strokeStyle='rgba(60,80,40,1)';c.lineWidth=1;c.beginPath();c.moveTo(0,-5.6*size);c.lineTo(1,-8*size);c.stroke();c.restore();}c.restore();}
// A sun shower: thin bright drops falling across a region, strength 0..1.
export function mfRain(c,x0,y0,w,h,t,strength=1,seed=5,L=null){if(strength<=0)return;const r=mpRng(seed);c.save();c.strokeStyle=L?mpRgb(mpLight(L.sun,.5),.55*strength):'rgba(255,255,255,'+(.55*strength)+')';c.lineWidth=1.1;c.lineCap='round';c.beginPath();for(let i=0;i<120;i++){const px=x0+r()*w,ph=r(),sp=.9+r()*.5;const u=((t*sp+ph)%1);const py=y0+u*h;c.moveTo(px-2,py-10);c.lineTo(px,py);}c.stroke();c.restore();}
// A rainbow: an arc centred at (x,y) of radius R, alpha a (0..1), the band fading at both ends.
export function mfRainbow(c,x,y,R,a,w=26){if(a<=0)return;const cols=[[255,60,60],[255,150,40],[255,230,60],[90,200,90],[70,150,240],[90,80,200]];c.save();c.globalCompositeOperation='screen';c.lineCap='butt';for(let i=0;i<cols.length;i++){c.strokeStyle=mpRgb(cols[i],a*.5);c.lineWidth=w/cols.length+.6;c.beginPath();c.arc(x,y,R-i*(w/cols.length),Math.PI*1.08,Math.PI*1.92);c.stroke();}c.restore();}
// Fireflies at dusk: n points of light wandering in a region, blinking.
export function mfFireflies(c,x0,y0,w,h,t,n,seed,strength=1){if(strength<=0)return;const r=mpRng(seed);c.save();c.globalCompositeOperation='screen';for(let i=0;i<n;i++){const ph=r()*100,sx=.2+r()*.3,sy=.15+r()*.3;const x=x0+w*(.5+.5*Math.sin(t*sx+ph)),y=y0+h*(.5+.5*Math.sin(t*sy+ph*1.7));const b=Math.max(0,Math.sin(t*2.2+ph*3));const g=c.createRadialGradient(x,y,0,x,y,7);g.addColorStop(0,`rgba(255,250,170,${.95*b*strength})`);g.addColorStop(.3,`rgba(240,230,120,${.5*b*strength})`);g.addColorStop(1,'rgba(240,230,120,0)');c.fillStyle=g;c.fillRect(x-7,y-7,14,14);}c.restore();}
// Lantern light: a warm glow at (x,y) with a flicker.
export function mfGlow(c,x,y,R,t,col=[255,200,110],a=.6){const f=.9+Math.sin(t*9+x)*.05+Math.sin(t*23+y)*.05;c.save();c.globalCompositeOperation='screen';const g=c.createRadialGradient(x,y,0,x,y,R);g.addColorStop(0,mpRgb(col,a*f));g.addColorStop(.4,mpRgb(col,a*f*.35));g.addColorStop(1,mpRgb(col,0));c.fillStyle=g;c.fillRect(x-R,y-R,R*2,R*2);c.restore();}
// Speed lines behind a thing moving in direction (dx,dy) at (x,y), strength 0..1.
export function mfSpeed(c,x,y,dx,dy,t,strength=1,len=40){if(strength<=0)return;c.save();c.strokeStyle=`rgba(255,255,255,${.6*strength})`;c.lineWidth=1.6;c.lineCap='round';const n=-Math.hypot(dx,dy)||1;const ux=dx/-n,uy=dy/-n;c.beginPath();for(let i=0;i<5;i++){const o=(i-2)*7;const px=x+(-uy)*o-ux*8,py=y+ux*o-uy*8;const l=len*(.5+((i*7+t*30)%10)/10);c.moveTo(px,py);c.lineTo(px-ux*l,py-uy*l);}c.stroke();c.restore();}
// A sweat drop at (x,y) (a worried character), from t0, 0.8 s.
export function mfSweat(c,x,y,t,t0,dir=1){const age=t-t0;if(age<0||age>.8)return;const u=age/.8;c.save();c.fillStyle='rgba(170,215,245,'+(1-u)+')';c.strokeStyle='rgba(60,80,110,'+(1-u)+')';c.lineWidth=1;c.beginPath();const px=x+dir*(4+u*8),py=y-6+u*14;c.moveTo(px,py-6);c.quadraticCurveTo(px+3.5,py+1,px,py+4);c.quadraticCurveTo(px-3.5,py+1,px,py-6);c.fill();c.stroke();c.restore();}
// A puff of a leaf storm in the wind: leaves flying across a region.
export function mfLeaves(c,x0,y0,w,h,t,strength,seed,L){if(strength<=0)return;const r=mpRng(seed);c.save();for(let i=0;i<18;i++){const ph=r(),sp=.5+r()*.5,amp=10+r()*20;const u=((t*sp*.25+ph)%1);const x=x0+u*w,y=y0+r()*h+Math.sin(t*3+ph*9)*amp;const col=r()<.5?[96,142,58]:[150,196,86];c.globalAlpha=strength*Math.sin(u*Math.PI);c.fillStyle=mpRgb(col);c.save();c.translate(x,y);c.rotate(t*4+ph*6);c.beginPath();c.ellipse(0,0,5,3,0,0,MF_TAU);c.fill();c.restore();}c.restore();}
// Wind: the lean of grass and cloth at time t for a gust shape; base 0..1 plus gusts from the list [[t0,strength],...].
export function mfWind(t,base=.2,gusts=[]){let w=base*(.7+.3*Math.sin(t*.7)+.15*Math.sin(t*2.3));for(const [t0,s,len] of gusts){const a=t-t0;if(a>=0&&a<(len||1.6)){const u=a/(len||1.6);w+=s*Math.sin(u*Math.PI);}}return w;}
